import{_ as e,o as d,c as r,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"你配过的指令 → 课程实现的机制","description":"","frontmatter":{},"headers":[],"relativePath":"nginx-internals-course/directives-map.md","filePath":"nginx-internals-course/docs/directives-map.md"}'),o={name:"nginx-internals-course/directives-map.md"};function c(i,t,n,l,s,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="你配过的指令-→-课程实现的机制" tabindex="-1">你配过的指令 → 课程实现的机制 <a class="header-anchor" href="#你配过的指令-→-课程实现的机制" aria-label="Permalink to &quot;你配过的指令 → 课程实现的机制&quot;">​</a></h1><p>学完课程回头看自己写过的 nginx.conf：每条常见指令背后是哪一章的机制，这张表负责把它们钉在一起。<strong>左列是你抄过的配置，右列是你亲手写过的代码。</strong></p><h2 id="指令对照" tabindex="-1">指令对照 <a class="header-anchor" href="#指令对照" aria-label="Permalink to &quot;指令对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你配过的</th><th>背后的机制</th><th>章</th></tr></thead><tbody><tr><td><code>worker_processes auto;</code></td><td>worker 数跟 CPU 核数走、不跟连接数走；master 建总机、worker 各自一个事件循环</td><td><a href="./07-master-workers.html">7</a></td></tr><tr><td><code>keepalive_timeout 65;</code></td><td>keep-alive：一条连接说完一件再说下一件，空闲超时由连接账本收割（TIME_WAIT 与端口耗尽那笔账）</td><td><a href="./04-keepalive-reuse.html">4</a></td></tr><tr><td><code>events { worker_connections 1024; }</code></td><td>每连接一个文件描述符的 1024 墙；连接注册表的上限拒绝</td><td><a href="./01-c10k-and-event-driven.html">1</a>、<a href="./02-connection-registry.html">2</a></td></tr><tr><td><code>large_client_header_buffers</code> / 请求行长限制</td><td>解析器的行长上限——慢速攻击（Slowloris）的解药</td><td><a href="./03-http-parser-state-machine.html">3</a></td></tr><tr><td><code>sendfile on;</code></td><td>零拷贝：数据不进程序内存，页缓存直达网卡，省两次 CPU 搬运</td><td><a href="./11-zero-copy-write-path.html">11</a></td></tr><tr><td><code>gzip on;</code>（写在 http/server/location 三层）</td><td>配置继承：子块覆盖、未写沿外层第一站取值</td><td><a href="./06-config-inheritance.html">6</a></td></tr><tr><td><code>proxy_pass http://backend;</code></td><td>反向代理：拨号上游、盖 X-Forwarded-For 邮戳、缓冲回写、失联回 502</td><td><a href="./08-reverse-proxy.html">8</a></td></tr><tr><td><code>upstream { server ...; }</code></td><td>后端名单：轮询分发 + 失败记账</td><td><a href="./09-load-balance.html">9</a></td></tr><tr><td><code>server b max_fails=2 fail_timeout=10s;</code></td><td>失败账：连续失败摘除、期满试探回归（<code>downUntil &lt;= now()</code>）</td><td><a href="./09-load-balance.html">9</a></td></tr><tr><td><code>limit_req zone=api rate=10r/s burst=20 nodelay;</code></td><td>漏桶：漏速=rate、桶容量=burst、nodelay=立即放行但占额度</td><td><a href="./10-rate-limit-leaky-bucket.html">10</a></td></tr><tr><td><code>limit_req_status 503;</code></td><td>溢出请求的拒绝码（默认 503，可配 429）</td><td><a href="./10-rate-limit-leaky-bucket.html">10</a></td></tr><tr><td><code>limit_req_zone ... key=$binary_remote_addr</code></td><td>一人一桶：按来源 IP 分桶，而不是按连接分桶（连接带端口，永远打不满）</td><td><a href="./10-rate-limit-leaky-bucket.html">10</a></td></tr></tbody></table><h2 id="你见过但课程未展开的-诚实清单" tabindex="-1">你见过但课程未展开的（诚实清单） <a class="header-anchor" href="#你见过但课程未展开的-诚实清单" aria-label="Permalink to &quot;你见过但课程未展开的（诚实清单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>一句话去向</th></tr></thead><tbody><tr><td><code>client_body_buffer_size</code> / <code>client_max_body_size</code></td><td>请求体的缓冲与上限——课程的解析器只到「头部结束」，body 定长读取是同族问题</td></tr><tr><td><code>proxy_buffering on/off</code></td><td>第 8 章「收齐再转」与「流式转发」的开关，课程实现的是简化版</td></tr><tr><td><code>proxy_http_version 1.1</code> + <code>upstream keepalive</code></td><td>上游连接池——课程每请求一条上游连接，省三次握手的账在第 4 章</td></tr><tr><td><code>least_conn;</code></td><td>负载均衡的另一规则：谁手头活少给谁（课程实现了轮询）</td></tr><tr><td><code>ssl_certificate ...</code></td><td>TLS 终结在反代——加密数据必须重新生成，sendfile 链条断点（第 11 章边界）</td></tr></tbody></table>',6)])])}const f=e(o,[["render",c]]);export{m as __pageData,f as default};
